package net.officefloor.hq.app.dashboard;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * A simple cash-flow forecast: the money expected in from instalments still to be paid on invoices that have been
 * sent, earliest due first, each in its invoice's currency, and all of them together as one total in the home
 * currency (each converted at the exchange rate from its invoice's issue date). Also what can be expected to be
 * collected in the next 30 days (see {@link Window}).
 */
public record ForecastResponse(String homeCurrency, List<Entry> entries, BigDecimal total, Window next30Days) {

    /**
     * What falls due on or between two dates, in the home currency: on a sent invoice paid by instalments, its unpaid
     * instalments due in the window; on any other sent invoice, what is left to pay on it when it is due in the window.
     */
    public record Window(LocalDate from, LocalDate to, BigDecimal total) {
    }

    /** One instalment expected in: when it is due, how much, and which invoice, job and client it is from. */
    public record Entry(Long id, LocalDate date, BigDecimal amount, String currency, Long invoiceId, Long projectId,
            String projectName, String clientName) {
    }
}
            total = total.add(invoice.getInstalmentInterestPerDay().multiply(BigDecimal.valueOf(daysLate))
                    .setScale(2, RoundingMode.HALF_UP));
        }
        return total;
    }

    /**
     * The money expected in from scheduled instalments: every instalment not yet paid on an invoice that has been
     * sent and is not yet fully paid, earliest due first, with the total in the home currency. A foreign instalment
     * converts at the exchange rate from its invoice's issue date; one whose currency has no rate by then is still
     * listed but left out of the total.
     */
    @Transactional(readOnly = true)
    public ForecastResponse forecast() {
        Map<Long, Invoice> open = invoices.findByStatusInWithClient(List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL))
                .stream().collect(Collectors.toMap(Invoice::getId, i -> i));
        String home = settings.homeCurrency();
        List<Instalment> due = open.isEmpty() ? List.of()
                : instalments.findByInvoiceIdIn(open.keySet()).stream().filter(i -> !i.isPaid())
                        .sorted(Comparator.comparing(Instalment::getDueDate).thenComparing(Instalment::getId))
                        .toList();
        BigDecimal total = BigDecimal.ZERO;
        List<ForecastResponse.Entry> entries = new ArrayList<>();
        for (Instalment instalment : due) {
            Invoice invoice = open.get(instalment.getInvoiceId());
            String currency = invoice.getCurrency();
            BigDecimal inHome = currency.equals(home) ? instalment.getAmount()
                    : fxRates.toHome(currency, invoice.getIssuedDate(), instalment.getAmount()).orElse(BigDecimal.ZERO);
            total = total.add(inHome);
            entries.add(new ForecastResponse.Entry(instalment.getId(), instalment.getDueDate(), instalment.getAmount(),
                    currency, invoice.getId(), invoice.getProject().getId(), invoice.getProject().getName(),
                    invoice.getProject().getClient().getName()));
        }
        LocalDate today = LocalDate.now(clock);
        return new ForecastResponse(home, entries, total.setScale(2, RoundingMode.HALF_UP),
                dueWithin(List.copyOf(open.values()), today, today.plusDays(FORECAST_DAYS), home));
    }

    /** How many days ahead the forecast of what can be collected looks. */
    static final int FORECAST_DAYS = 30;

    /**
     * What can be expected to be collected on or between the given dates, in the home currency, from the given open
     * invoices (disputed ones are left out): an invoice paid by instalments brings in its unpaid instalments due in the
     * window; any other brings in what is left to pay on it when its due date is in the window. Anything already
     * overdue is not counted. A foreign amount converts at its invoice's issue date's rate; one that cannot be
import { Component, inject } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService } from './dashboard.service';

// A simple cash-flow forecast: the money expected in from instalments still to be paid on sent invoices,
// earliest due first, with the total in the home currency, and what can be expected to be collected in the next 30 days.
@Component({
  selector: 'app-cash-flow-forecast',
  imports: [MoneyPipe, RouterLink],
  template: `
    <section aria-labelledby="forecast-heading" data-testid="forecast">
      <h2 id="forecast-heading">Cash-flow forecast</h2>
      @if (forecast.error()) {
        <p role="alert" data-testid="forecast-error">Could not load the forecast.</p>
      } @else if (forecast.value(); as f) {
        <p>
          Expected in the next 30 days ({{ f.next30Days.from }} to {{ f.next30Days.to }}):
          <strong data-testid="forecast-30day-total">{{ f.next30Days.total | money: f.homeCurrency }}</strong>
        </p>
        @if (f.entries.length === 0) {
          <p data-testid="forecast-empty">No instalments expected in.</p>
        } @else {
          <table>
            <thead>
              <tr>
                <th scope="col">Due</th>
                <th scope="col">Job</th>
                <th scope="col">Client</th>
                <th scope="col">Amount</th>
              </tr>
            </thead>
            <tbody>
              @for (e of f.entries; track e.id) {
                <tr [attr.data-testid]="'forecast-row-' + e.id">
                  <td data-testid="forecast-date">{{ e.date }}</td>
                  <td data-testid="forecast-project">
                    <a [routerLink]="['/projects', e.projectId]">{{ e.projectName }}</a>
                  </td>
                  <td data-testid="forecast-client">{{ e.clientName }}</td>
                  <td data-testid="forecast-amount">{{ e.amount | money: e.currency }}</td>
                </tr>
              }
            </tbody>
            <tfoot>
              <tr>
                <th scope="row" colspan="3">Total expected (in {{ f.homeCurrency }})</th>
                <td data-testid="forecast-total">{{ f.total | money: f.homeCurrency }}</td>
              </tr>
            </tfoot>
          </table>
        }
      } @else {
        <p data-testid="forecast-loading">Loading…</p>
      }
    </section>
  `,
})
export class CashFlowForecast {
  private readonly service = inject(DashboardService);

  protected readonly forecast = rxResource({ stream: () => this.service.forecast() });
}

